    'onboarding.role_admin_desc': 'This is the interface you are using right now. Admin does not handle <strong>any HTTP traffic</strong> — it manages configuration, users, pairing tokens and monitoring. If Admin is temporarily unavailable, your proxies keep running.',
    'onboarding.role_core_title': 'Core — data plane',
    'onboarding.role_core_desc': 'Core is the <strong>active reverse proxy</strong>. It listens on ports 80 and 443, manages TLS certificates via ACME and applies all routing rules. It is the <strong>source of truth</strong>: each Core stores its own configuration and can run fully autonomously. You can deploy multiple Cores to distribute load or cover multiple datacenters.',
    'onboarding.role_agent_title': 'Agent — automatic discovery <span style="font-size:11px;font-weight:400;color:var(--text3);">(optional)</span>',
    'onboarding.role_agent_desc': 'Agent monitors Docker containers or Kubernetes services on a host. When a container starts with the right labels, Agent notifies Core which automatically creates the proxy rule. Agent is not required if you manage proxies manually.',
    'onboarding.in_practice': 'In practice:',
    'onboarding.practice_full': 'you deploy a Core on your server with a pairing token generated by this Admin. The Core connects, sends its heartbeat, and you can immediately create proxies. Admin can be rebuilt at any time from Core state — your data is never lost.',
    'onboarding.practice_short': 'deploy a Core with the pairing secret. It enters pending — you accept it here. Your proxies keep running even if Admin is temporarily unavailable.',
