    'onboarding.role_admin_title': 'Admin — le plan de contrôle',
    'onboarding.role_admin_desc': 'C\'est l\'interface que vous utilisez en ce moment. L\'Admin ne touche <strong>aucun trafic HTTP</strong> — il gère la configuration, les utilisateurs, les tokens d\'appairage et la supervision. Si l\'Admin est temporairement indisponible, vos proxies continuent de fonctionner.',
    'onboarding.role_core_title': 'Core — le plan de données',
    'onboarding.role_core_desc': 'Le Core est le <strong>reverse proxy actif</strong>. Il écoute sur les ports 80 et 443, gère les certificats TLS via ACME et applique toutes les règles de routage. C\'est lui la <strong>source de vérité</strong> : chaque Core stocke sa propre configuration et peut fonctionner de manière totalement autonome. Vous pouvez déployer plusieurs Cores pour répartir la charge ou couvrir plusieurs datacenters.',
    'onboarding.role_agent_title': 'Agent — la découverte automatique <span style="font-size:11px;font-weight:400;color:var(--text3);">(optionnel)</span>',
    'onboarding.role_agent_desc': 'L\'Agent surveille les conteneurs Docker ou les services Kubernetes sur un hôte. Dès qu\'un conteneur démarre avec les bons labels, l\'Agent le signale au Core qui crée automatiquement la règle de proxy. L\'Agent n\'est pas nécessaire si vous gérez vos proxies manuellement.',
    'onboarding.in_practice': 'En pratique :',
    'onboarding.practice_full': 'vous déployez un Core sur votre serveur avec un token d\'appairage généré par cet Admin. Le Core se connecte, envoie son heartbeat, et vous pouvez immédiatement créer des proxies. L\'Admin peut être reconstruit à tout moment depuis l\'état des Cores — vos données ne sont jamais perdues.',
    'onboarding.practice_short': 'déployez un Core avec le secret d\'appairage. Il entre en attente — vous l\'acceptez ici. Vos proxies fonctionnent même si l\'Admin est temporairement indisponible.',
