    'onboarding.role_admin_title': 'Admin — plano de control',
    'onboarding.role_admin_desc': 'Esta es la interfaz que está usando ahora. Admin no gestiona <strong>ningún tráfico HTTP</strong> — administra configuración, usuarios, tokens de emparejamiento y monitoreo. Si Admin no está disponible temporalmente, sus proxies siguen funcionando.',
    'onboarding.role_core_title': 'Core — plano de datos',
    'onboarding.role_core_desc': 'Core es el <strong>reverse proxy activo</strong>. Escucha en los puertos 80 y 443, gestiona certificados TLS vía ACME y aplica todas las reglas de enrutamiento. Es la <strong>fuente de verdad</strong>: cada Core almacena su propia configuración y puede funcionar de forma totalmente autónoma. Puede desplegar varios Cores para distribuir la carga o cubrir varios datacenters.',
