function gpxParseLocale(tag) {
  if (!tag) return 'en';
  const base = String(tag).toLowerCase().split(/[-_]/)[0];
  if (GPX_I18N_LOCALES.indexOf(base) >= 0) return base;
  return 'en';
}

function gpxBCP47() {
  switch (gpxResolveLocale()) {
    case 'fr': return 'fr-FR';
    case 'es': return 'es-ES';
    case 'de': return 'de-DE';
    default: return 'en-US';
  }
}

function gpxResolveLocale() {
  try {
    let o = localStorage.getItem(GPX_I18N_STORAGE_KEY);
    if (!o) {
      const legacy = localStorage.getItem('gpx_lang');
      if (legacy && GPX_I18N_LOCALES.indexOf(legacy) >= 0) {
        o = legacy;
        try { localStorage.setItem(GPX_I18N_STORAGE_KEY, o); } catch (_) {}
      }
    }
    if (o && GPX_I18N_LOCALES.indexOf(o) >= 0) return o;
  } catch (_) { /* private mode */ }
  if (typeof navigator !== 'undefined' && navigator.language) {
    return gpxParseLocale(navigator.language);
  }
  return 'en';
}

function gpxHasLocaleOverride() {
  try {
    const o = localStorage.getItem(GPX_I18N_STORAGE_KEY);
    return !!(o && GPX_I18N_LOCALES.indexOf(o) >= 0);
  } catch (_) { return false; }
}

function gpxSetLocale(loc) {
  const v = gpxParseLocale(loc);
  try {
    localStorage.setItem(GPX_I18N_STORAGE_KEY, v);
    localStorage.setItem('gpx_lang', v); // legacy picker compat
  } catch (_) {}
  document.documentElement.lang = v;
  return v;
}

function gpxClearLocaleOverride() {
  try {
    localStorage.removeItem(GPX_I18N_STORAGE_KEY);
    localStorage.removeItem('gpx_lang');
  } catch (_) {}
  document.documentElement.lang = gpxResolveLocale();
}

/** Translate key; missing pack entries fall back to EN; unknown key returns key. */
function t(key, vars) {
  const loc = gpxResolveLocale();
  const packs = GPX_I18N_MESSAGES;
  let msg = (packs[loc] && packs[loc][key]) || (packs.en && packs.en[key]) || key;
  if (vars && typeof vars === 'object') {
    Object.keys(vars).forEach(function (k) {
      msg = msg.replace(new RegExp('\\{' + k + '\\}', 'g'), String(vars[k]));
    });
  }
  return msg;
}

function gpxPageLabel(page, fallback) {
  const k = 'page.' + page;
  const v = t(k);
  return v === k ? (fallback || page) : v;
}

function gpxNavSectionLabel(label) {
  const k = 'nav.section.' + label;
  const v = t(k);
  return v === k ? label : v;
}

function applyStaticI18n(root) {
  const scope = root || document;
  scope.querySelectorAll('[data-i18n]').forEach(function (el) {
    const key = el.getAttribute('data-i18n');
    if (key) el.textContent = t(key);
  });
  scope.querySelectorAll('[data-i18n-html]').forEach(function (el) {
    const key = el.getAttribute('data-i18n-html');
    if (key) el.innerHTML = t(key);
  });
  scope.querySelectorAll('[data-i18n-placeholder]').forEach(function (el) {
    const key = el.getAttribute('data-i18n-placeholder');
    if (key) el.setAttribute('placeholder', t(key));
  });
  scope.querySelectorAll('[data-i18n-title]').forEach(function (el) {
    const key = el.getAttribute('data-i18n-title');
    if (key) el.setAttribute('title', t(key));
  });
  scope.querySelectorAll('[data-i18n-aria]').forEach(function (el) {
    const key = el.getAttribute('data-i18n-aria');
    if (key) el.setAttribute('aria-label', t(key));
  });
  if (document.title !== undefined) {
    document.title = t('doc.title');
  }
  const tl = document.getElementById('login-branding-tagline');
  if (tl) tl.textContent = t('brand.tagline');
}

function gpxRefreshUILocale() {
  document.documentElement.lang = gpxResolveLocale();
  applyStaticI18n();
  if (typeof renderNav === 'function' && typeof state !== 'undefined') {
    renderNav(state.user || null);
  }
  if (typeof state !== 'undefined' && state.page && typeof navigate === 'function') {
    navigate(state.page);
  }
  if (typeof tickTopbarClock === 'function') tickTopbarClock();
}

(function () {
  try {
    document.documentElement.lang = gpxResolveLocale();
  } catch (_) {}
})();
